def solve(r,n,t):
 P=list(range(1<<r)); Q=[frozenset([i]) for i in range(n)]+[frozenset(e) for e in itertools.combinations(range(n),2)]
 X=list(itertools.product(P,Q)); N=len(X)
 le=lambda a,b: a[0]&b[0]==a[0] and a[1]<=b[1]
 D=[{j for j in range(N) if j!=i and le(X[j],X[i])} for i in range(N)]
 U=[{j for j in range(N) if j!=i and le(X[i],X[j])} for i in range(N)]
 crit=[(i,j) for i in range(N) for j in range(N) if i!=j and not le(X[i],X[j]) and not le(X[j],X[i]) and D[i]<=D[j] and U[j]<=U[i]]
 s=z3.Solver();s.set(timeout=90000)
 a=[[z3.Int(f'a{k}_{i}') for i in range(N)] for k in range(t)]
 for k in range(t):
  for i in range(N):
   s.add(a[k][i]>=0,a[k][i]<N)
   for j in U[i]:s.add(a[k][i]<a[k][j])
 for i,j in crit:s.add(z3.Or([a[k][i]>a[k][j] for k in range(t)]))
 print(r,n,t,'N',N,'crit',len(crit),s.check(),flush=True)
for t in [3,4,5,6]:solve(3,3,t)

