import itertools,z3

def solve(r,n,t):
 # critical pairs explicitly P coordinate and Q coordinate, order constraints compress using min/max P
 P=list(range(1<<r)); Q=[frozenset([i]) for i in range(n)]+[frozenset(e) for e in itertools.combinations(range(n),2)]
 X=list(itertools.product(P,Q));N=len(X); idx={x:i for i,x in enumerate(X)}
 s=z3.Solver();s.set(timeout=60000)
 a=[[z3.Int(f'a{k}_{i}') for i in range(N)] for k in range(t)]
 for k in range(t):
  for i,(p,q) in enumerate(X):
   s.add(a[k][i]>=0,a[k][i]<N)
   for bit in range(r):
    if not p>>bit&1:s.add(a[k][i]<a[k][idx[(p|1<<bit,q)]])
   if len(q)==1:
    for e in Q[n:]:
     if q<e:s.add(a[k][i]<a[k][idx[(p,e)]])
 crit=[]
 for v in Q[:n]:
  for e in Q[n:]:
   if v<e:
    for bit in range(r):crit.append((idx[(1<<bit,v)],idx[(((1<<r)-1)^(1<<bit),e)]))
   elif not v<=e:crit.append((idx[(0,v)],idx[((1<<r)-1,e)]))
 for i,j in crit:s.add(z3.Or([a[k][i]>a[k][j] for k in range(t)]))
 print(r,n,t,s.check(),flush=True)
for n,t in [(10,5),(12,5),(13,6),(13,5)]:solve(3,n,t)

