for m in [3,4,5,6]:
 r=3;n=3;Q=[frozenset([i]) for i in range(n)]+[frozenset(e) for e in itertools.combinations(range(n),2)];P=list(itertools.product(range(m),repeat=r));X=list(itertools.product(P,Q));N=len(X);idx={x:i for i,x in enumerate(X)}
 s=z3.Solver();s.set(timeout=45000);t=4;a=[[z3.Int(f'a{k}_{i}') for i in range(N)] for k in range(t)]
 for k in range(t):
  for i,(p,q) in enumerate(X):
   for bit in range(r):
    if p[bit]<m-1:
     pp=list(p);pp[bit]+=1;s.add(a[k][i]<a[k][idx[(tuple(pp),q)]])
   if len(q)==1:
    for e in Q[n:]:
     if q<e:s.add(a[k][i]<a[k][idx[(p,e)]])
 crit=[]
 for v in Q[:n]:
  for e in Q[n:]:
   if v<e:
    for bit in range(r):
     for h in range(1,m):
      pp=[0]*r;pp[bit]=h;qq=[m-1]*r;qq[bit]=h-1;crit.append((idx[(tuple(pp),v)],idx[(tuple(qq),e)]))
   else:crit.append((idx[((0,)*r,v)],idx[((m-1,)*r,e)]))
 for i,j in crit:s.add(z3.Or([a[k][i]>a[k][j] for k in range(t)]))
 print(m,N,s.check(),flush=True)

